{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C54"],
      "claim": "Edaravone, an N-phenyl pyrazolone closely related to the query core, has an absolute oral bioavailability of 57.3% in humans, directly supporting F ≥ 20% for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Clobazam, an N-aryl heterocycle, is reported to have 90–100% oral bioavailability, supporting high oral absorption for N-aryl heteroaromatic drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Roquinimex, an N-phenyl quinolinone amide, shows complete oral bioavailability in healthy volunteers, supporting high F for N-aryl amide/lactam structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Laquinimod, a close roquinimex analogue, has approximately 80–90% oral bioavailability, reinforcing high F for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Imidafenacin has an absolute oral bioavailability of 57.8% in healthy subjects, providing additional support for high F in N-aryl/heteroaryl drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "5-Hydroxyrofecoxib has a low oral bioavailability (~14%), but its sulfone/lactone structure is less transferable to the query; this is the main contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable experimental evidence from structurally related N-aryl pyrazolones and heteroaromatic drugs indicates high oral bioavailability (F ≥ 20%). The low-F examples are structurally more distant and carry less weight.",
  "evidence_gaps": [
    "No direct absolute F measurement for the exact query molecule.",
    "The query is a sulfonate prodrug; reported bioavailability may refer to the active metabolite rather than the parent compound.",
    "Morgan similarities to evidence molecules are low, limiting quantitative transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

